function page(){return String(window.WAFFLE_PAGE||document.body?.dataset?.wafflePage||'calendar')}
function clean(v){return String(v||'').toLowerCase().replace(/[’']/g,'').replace(/[–—]/g,'-').replace(/[^a-z0-9\s/&.-]/g,' ').replace(/\s+/g,' ').trim()}
